export interface Camera {
    x: number;
    y: number;
    zoom: number;
}

export class CameraSystem {
    // Current State
    public x: number = 0;
    public y: number = 0;
    public zoom: number = 1.0;

    // Target State (Where the director or physics wants to go)
    private targetX: number = 0;
    private targetY: number = 0;
    private targetZoom: number = 1.0;

    // Physics
    private vx: number = 0;
    private vy: number = 0;
    private vz: number = 0; // Velocity for zoom

    // Parameters
    private readonly FRICTION = 0.90;        // 慣性滑動摩擦力
    private readonly FOLLOW_STIFFNESS = 3.0; // 跟隨力度 (越低越滑順，越高越緊)
    private readonly ZOOM_STIFFNESS = 2.0;   // 縮放力度 (通常比移動慢)
    private readonly DECAY_RATE = 8.0;       // 震動衰減

    // Mode Control
    private manualOverrideTimer: number = 0; // 手動操作後的冷卻時間
    private isManualControlling: boolean = false;

    private trauma: number = 0;

    constructor() {}

    // 初始化或瞬間跳轉
    public snapTo(x: number, y: number, zoom: number) {
        this.x = this.targetX = x;
        this.y = this.targetY = y;
        this.zoom = this.targetZoom = zoom;
        this.vx = 0;
        this.vy = 0;
        this.vz = 0;
    }

    public reset() { 
        this.trauma = 0; 
        this.vx = 0; this.vy = 0; this.vz = 0;
        this.manualOverrideTimer = 0;
    }

    // 外部同步 (React State -> Engine)
    public sync(camera: Camera) {
        // 如果處於手動模式，我們信任外部傳入的座標作為「目標」
        // 但不直接覆蓋 this.x/y，保留平滑過渡的可能性
        if (this.isManualControlling) {
            this.targetX = camera.x;
            this.targetY = camera.y;
            this.targetZoom = camera.zoom;
        }
    }

    // 當玩家拖曳畫面時呼叫
    public applyPanOffset(dx: number, dy: number) {
        this.isManualControlling = true;
        this.manualOverrideTimer = 2.0; // 手動操作後，暫停導播 2 秒

        const factor = 1.0 / this.zoom;
        const worldDx = dx * factor;
        const worldDy = dy * factor;

        // 直接操縱：立即更新位置以達到跟手感
        this.x -= worldDx;
        this.y -= worldDy;
        this.targetX = this.x;
        this.targetY = this.y;

        this.vx = 0;
        this.vy = 0;
    }

    public applyZoom(targetZoom: number) {
        // 縮放通常也視為手動介入，但我們可以讓它平滑一點
        this.targetZoom = targetZoom;
        // 如果是滾輪縮放，我們不一定需要完全禁用到導播位移，但為了保險起見：
        this.manualOverrideTimer = 1.0; 
    }

    // 導播系統的輸入接口
    public setDirectorTarget(x: number, y: number, zoom: number) {
        // 只有在非手動模式下，導播系統才能控制目標點
        if (this.manualOverrideTimer <= 0) {
            this.isManualControlling = false;
            this.targetX = x;
            this.targetY = y;
            this.targetZoom = zoom;
        }
    }

    public addTrauma(amount: number) {
        this.trauma = Math.min(1.0, this.trauma + amount);
    }

    public getTrauma(): number {
        return this.trauma;
    }

    public update(dt: number) {
        // 1. Trauma Decay
        if (this.trauma > 0) {
            this.trauma = Math.max(0, this.trauma - dt * this.DECAY_RATE);
        }

        // 2. Manual Timer Decay
        if (this.manualOverrideTimer > 0) {
            this.manualOverrideTimer -= dt;
            if (this.manualOverrideTimer <= 0) {
                this.isManualControlling = false;
            }
        }

        // 3. Cinematic Smoothing (Exponential Interpolation)
        // 使用 dt 相關的 Lerp 公式: Current += (Target - Current) * (1 - exp(-speed * dt))
        // 這保證了 Frame Rate 獨立性且極度平滑

        // Position Smoothing
        const panFactor = 1.0 - Math.exp(-this.FOLLOW_STIFFNESS * dt);
        this.x += (this.targetX - this.x) * panFactor;
        this.y += (this.targetY - this.y) * panFactor;

        // Zoom Smoothing (Slower)
        const zoomFactor = 1.0 - Math.exp(-this.ZOOM_STIFFNESS * dt);
        this.zoom += (this.targetZoom - this.zoom) * zoomFactor;

        // 4. Momentum (Optional, currently simplified to direct damped follow for better framing)
        // 如果未來需要甩動慣性，可以在這裡加入 vx/vy 的積分
    }

    public applyTransform(ctx: CanvasRenderingContext2D, width: number, height: number) {
        const cx = width / 2;
        const cy = height / 2;

        let shakeX = 0, shakeY = 0;
        if (this.trauma > 0) {
            // Screen Shake: Trauma^2 * MaxOffset
            // 使用 Perlin Noise 會更好，這裡用隨機數簡化
            const p = this.trauma * this.trauma;
            const maxShake = 30 * this.zoom; // Zoom 越大震動感越強
            const angle = Math.random() * Math.PI * 2;
            shakeX = Math.cos(angle) * maxShake * p;
            shakeY = Math.sin(angle) * maxShake * p;
        }

        // 應用變換：先移到畫面中心 -> 縮放 -> 移回攝影機位置
        // 注意：攝影機座標 (x,y) 是世界座標的中心點
        const targetTx = cx - (this.x + shakeX) * this.zoom;
        const targetTy = cy - (this.y + shakeY) * this.zoom;

        ctx.translate(targetTx, targetTy); // 使用 float 讓移動更滑順，避免像素抖動
        ctx.scale(this.zoom, this.zoom);
    }
}

import { GameEngine, Agent } from "../game";
import { HexUtils } from "../utils";
import { Point } from "../../types";

export class DirectorSystem {
    // Configuration
    private readonly IDLE_ZOOM = 0.9;
    private readonly COMBAT_ZOOM = 1.15;
    private readonly ULT_ZOOM = 1.45;

    // State
    private currentFocusPoint: Point = { x: 0, y: 0 };
    private currentZoomLevel: number = 1.0;

    // 興趣點平滑過渡用
    private lastCentroidX: number = 0;
    private lastCentroidY: number = 0;
    private hasInitialized: boolean = false;

    public reset(engine: GameEngine) {
        const ds = engine.state.director;
        ds.targetId = null;
        ds.focusTimer = 0;
        ds.priorityTimer = 0;
        this.hasInitialized = false;
    }

    public forceFocus(engine: GameEngine, id: string, duration: number = 2.0) {
        const ds = engine.state.director;
        ds.targetId = id;
        ds.priorityTimer = duration; // 優先權計時器，防止被普通邏輯覆蓋
        ds.focusTimer = duration;
    }

    public update(engine: GameEngine, dt: number) {
        const ds = engine.state.director;

        // 1. Timer Logic
        if (ds.priorityTimer > 0) ds.priorityTimer -= dt;
        if (ds.focusTimer > 0) ds.focusTimer -= dt;

        // 2. Select Target (Decision Making)
        this.decideTarget(engine, ds);

        // 3. Calculate Cinematic Frame (Computation)
        const frame = this.calculateFrame(engine, ds.targetId);

        // 4. Push to Camera System (Action)
        if (engine.renderer && frame) {
            engine.renderer.camera.setDirectorTarget(frame.x, frame.y, frame.zoom);
        }
    }

    private decideTarget(engine: GameEngine, ds: any) {
        // 如果有強制優先權 (如奧義剛放)，不切換目標
        if (ds.priorityTimer > 0) return;

        // 如果當前目標無效或計時結束，尋找新目標
        let needNewTarget = false;

        if (ds.targetId) {
            const current = engine.agents.find(a => a.id === ds.targetId);
            if (!current || current.hp <= 0 || current.banished) {
                needNewTarget = true;
            } else if (ds.focusTimer <= 0) {
                // 時間到，嘗試切換更有趣的目標
                needNewTarget = true; 
            }
        } else {
            needNewTarget = true;
        }

        if (needNewTarget) {
            const bestCandidate = this.findBestCandidate(engine);
            if (bestCandidate) {
                // 如果目標改變了，設定新的關注時間
                if (ds.targetId !== bestCandidate.id) {
                    ds.targetId = bestCandidate.id;
                    // 根據動作給予不同的鏡頭時間
                    // 奧義/施法：給多一點時間 (3-4s)
                    // 移動/被打：給少一點時間 (2-3s)
                    const isAction = bestCandidate.castingSkillIdx !== -1;
                    ds.focusTimer = isAction ? 4.0 : 2.5;
                }
            } else {
                // 沒人活著，清空目標 (鏡頭將飄向戰場中心)
                ds.targetId = null;
            }
        }
    }

    private findBestCandidate(engine: GameEngine): Agent | null {
        let candidates: Agent[] = [];
        let maxScore = -1;
        let best: Agent | null = null;

        for (const a of engine.agents) {
            if (a.hp <= 0 || a.banished) continue;

            // 評分系統 (Director Scoring)
            let score = Math.random() * 10; // 基礎隨機性，避免死板

            // A. 狀態加權
            if (a.castingSkillIdx !== -1) {
                const skill = a.skills[a.castingSkillIdx];
                if (skill?.tag === 'ULT') score += 50; // 奧義極高權重
                else if (skill?.tag === 'ACTIVE') score += 20;
                else score += 5; // 普攻
            }
            if (a.hitFlashTimer > 0) score += 15; // 正在被打
            if (a.isMoving) score += 5;

            // B. 職業加權 (DPS 和 Tank 打架比較好看)
            if (a.role === 'WARRIOR' || a.role === 'TANK') score += 2;

            if (score > maxScore) {
                maxScore = score;
                best = a;
            }
        }
        return best;
    }

    private calculateFrame(engine: GameEngine, targetId: string | null): { x: number, y: number, zoom: number } | null {
        let targetX = 0;
        let targetY = 0;
        let targetZoom = this.IDLE_ZOOM;

        const mainActor = targetId ? engine.agents.find(a => a.id === targetId) : null;

        if (mainActor && mainActor.hp > 0) {
            // --- 戰鬥構圖邏輯 ---

            // 1. 基礎位置：主角
            targetX = mainActor.px;
            targetY = mainActor.py;

            // 2. 關係修正：如果有攻擊目標，鏡頭移向兩者中間
            if (mainActor.target && mainActor.target.hp > 0) {
                const t = mainActor.target;

                // 權重平均：主角 60%，目標 40% (讓鏡頭稍微偏向主角)
                targetX = mainActor.px * 0.6 + t.px * 0.4;
                targetY = mainActor.py * 0.6 + t.py * 0.4;

                // 3. 動態縮放：根據距離調整
                // 距離越近，Zoom 越大 (Close up fight)
                const dist = HexUtils.dist(mainActor, t); // Hex distance
                if (dist < 2) targetZoom = this.COMBAT_ZOOM; // Close combat
                else if (dist < 6) targetZoom = 1.05;        // Mid range
                else targetZoom = 0.95;                      // Long range sniping

            } else if (mainActor.isMoving && mainActor.path.length > 0) {
                // 如果在移動，鏡頭稍微看向前方 (Look Ahead)
                // 預判 100px
                targetX += mainActor.physics.vx * 0.5; 
                targetY += mainActor.physics.vy * 0.5;
                targetZoom = 1.0;
            } else {
                // 待機特寫
                targetZoom = 1.1; 
            }

            // 4. 奧義特寫 override
            if (mainActor.castingSkillIdx !== -1) {
                const skill = mainActor.skills[mainActor.castingSkillIdx];
                if (skill?.tag === 'ULT') {
                    // 奧義時，鏡頭聚焦於施法者，並拉近
                    targetX = mainActor.px;
                    targetY = mainActor.py - 20; // 稍微抬高一點構圖
                    targetZoom = this.ULT_ZOOM;
                }
            }

        } else {
            // --- 廣角模式 ---
            // 沒有特定目標，計算所有存活單位的重心
            let sumX = 0, sumY = 0, count = 0;
            for (const a of engine.agents) {
                if (a.hp > 0) {
                    sumX += a.px;
                    sumY += a.py;
                    count++;
                }
            }

            if (count > 0) {
                targetX = sumX / count;
                targetY = sumY / count;
                // 根據單位分佈廣度調整 Zoom? 暫時固定廣角
                targetZoom = this.IDLE_ZOOM;
            } else {
                // 完全沒人，看地圖中心
                const centerHex = { q: Math.floor(engine.mapConfig.w/2), r: Math.floor(engine.mapConfig.h/2) };
                const centerPx = HexUtils.toPx(centerHex.q, centerHex.r, engine.mapConfig);
                targetX = centerPx.x;
                targetY = centerPx.y;
                targetZoom = 0.8;
            }
        }

        // --- 平滑重心 (Stabilizer) ---
        // 避免因為目標切換導致瞬間座標跳變
        if (!this.hasInitialized) {
            this.lastCentroidX = targetX;
            this.lastCentroidY = targetY;
            this.hasInitialized = true;
        }

        // 這裡做一層極輕微的緩衝，防止計算出的 frame 跳動
        // 真正的物理慣性由 CameraSystem 處理
        this.lastCentroidX += (targetX - this.lastCentroidX) * 0.1;
        this.lastCentroidY += (targetY - this.lastCentroidY) * 0.1;

        return { x: targetX, y: targetY, zoom: targetZoom };
    }
}

import { DEFAULT_SKILL_DB } from "../skillDatabase";
import { SCENE_DB } from "../data/scenes";
import { LogEntry, NodeState, Role, Skill, Team, Projectile, GameEvent, GameEventType, AnimState, SceneTheme, Hex, MovementType, LogActionType, HexLayout, GroundHazard, GlobalSessionState } from "../types";
import { BTNode } from "./behaviorTree";
import { HexUtils, MapConfig } from "./utils";
import { DEFAULT_HEX_LAYOUT } from "../constants";
import { Agent, SpecialVisualStatus } from "./core/Agent";
import { MovementSystem } from "./systems/movement";
import { PhysicsSystem } from "./systems/PhysicsSystem"; 
import { CombatSystem } from "./systems/combat";
import { MapSystem } from "./systems/map";
import { HazardSystem } from "./systems/HazardSystem"; 
import { AISystem } from "./systems/ai";
import { AgentManager } from "./systems/agentManager";
import { AnnouncerSystem } from "./systems/AnnouncerSystem"; 
import { DirectorSystem } from "./systems/DirectorSystem"; 
import { BattleLogger } from "./systems/BattleLogger"; 
import { TimeSystem } from "./systems/TimeSystem"; 
import { VictorySystem } from "./systems/VictorySystem"; 
import { ZoneSystem } from "./systems/ZoneSystem"; 
import { EventBus } from "./events/EventBus";
import { EventPool } from "./events/GameEventPool"; 
import { CooldownSystem } from "./systems/status/CooldownSystem";
import { EffectSystem } from "./systems/status/EffectSystem";
import { ControlSystem } from "./systems/status/ControlSystem";
import type { GameRenderer } from "./renderer";

export { Agent, SpecialVisualStatus };

export const VICTORY_PHASE_DURATION = 0.5; 

export class GameEngine {
    public agents: Agent[] = [];
    public projectiles: Projectile[] = [];

    public state = {
        director: { focusTimer: 0, priorityTimer: 0, targetId: null as string | null },
        hazards: new Map<string, GroundHazard>(),
        victory: { victoryTimer: 0, winningTeam: null as Team | null, isFinishing: false },
        time: { battleTime: 0, timeScale: 1.0, targetTimeScale: 1.0 }
    };

    public sessionState: GlobalSessionState = {
        killStreaks: new Map(),
        firstBloodTriggered: false,
        directorTargetId: null,
        directorTimer: 0,
        directorPriorityTimer: 0
    };

    get hazards() { return this.state.hazards; }
    get battleTime() { return this.state.time.battleTime; }
    set battleTime(v: number) { this.state.time.battleTime = v; }
    get timeScale() { return this.state.time.timeScale; }
    set timeScale(v: number) { this.state.time.timeScale = v; }
    get targetTimeScale() { return this.state.time.targetTimeScale; }
    set targetTimeScale(v: number) { this.state.time.targetTimeScale = v; }
    get victory() { return this.state.victory; }

    get directorTargetId() { return this.state.director.targetId; }
    get mapKeys() { return this.map.mapKeys; }
    get obstacles() { return this.map.obstacles; }
    get agentMap() { return this.map.agentMap; }
    get logs() { return this.logger.logs; }

    public events: GameEvent[] = [];
    public bus: EventBus = new EventBus();
    public renderer?: GameRenderer;
    public isRunning: boolean = false;
    public mapVersion: number = 0; 

    public mapConfig: MapConfig = { w: 12, h: 8, offsetX: 0, offsetY: 0, layout: DEFAULT_HEX_LAYOUT };
    public currentScene: SceneTheme = SCENE_DB[0];
    public skillDB: Skill[] = [...DEFAULT_SKILL_DB];

    public movement: MovementSystem = new MovementSystem();
    public physics: PhysicsSystem = new PhysicsSystem(); 
    public combat: CombatSystem = new CombatSystem();
    public map: MapSystem = new MapSystem();
    public hazardSystem: HazardSystem = new HazardSystem();
    public ai: AISystem = new AISystem();
    public agentManager: AgentManager = new AgentManager();
    public announcer: AnnouncerSystem = new AnnouncerSystem(); 
    public director: DirectorSystem = new DirectorSystem();
    public logger: BattleLogger = new BattleLogger(); 
    public victorySystem: VictorySystem = new VictorySystem(); 
    public zones: ZoneSystem = new ZoneSystem(); 
    public cooldowns: CooldownSystem = new CooldownSystem();
    public effects: EffectSystem = new EffectSystem();
    public controls: ControlSystem = new ControlSystem();
    public timeSystem: TimeSystem = new TimeSystem();

    constructor() {
        this.map.randomizeEnvironment(this);
    }

    public addAgent(team: Team, q: number, r: number, hpOverride?: number, roleOverride?: Role) { 
        return this.agentManager.addAgent(this, team, q, r, hpOverride, roleOverride); 
    }
    public isValid(q: number, r: number) { return this.map.isValid(q, r); }
    public isBlocked(q: number, r: number, ignoreId?: string, movementType: MovementType = MovementType.GROUND) { return this.map.isBlocked(q, r, this, ignoreId, movementType); }
    public isValidHash(h: number) { return this.map.isValidHash(h); }
    public hasObstacle(q: number, r: number) { return this.map.hasObstacle(q, r); }
    public hasObstacleHash(h: number) { return this.map.hasObstacleHash(h); }
    public getTerrainHeight(q: number, r: number) { return this.map.getTerrainHeight(q, r); }

    public randomizeEnvironment() { 
        this.state.hazards.clear(); 
        if (this.renderer) this.renderer.vfx.reset(); 
        this.map.randomizeEnvironment(this); 
    }

    public rebuildMap() { 
        this.state.hazards.clear();
        this.map.rebuildMap(this); 
    }

    public removeAgent(q: number, r: number) {
        const agent = this.map.getAgentAt(q, r);
        if (agent) {
            this.agents = this.agents.filter(a => a !== agent);
            this.map.unregisterAgent(agent);
        }
    }

    public getAgentAt(q: number, r: number): Agent | undefined {
        return this.map.getAgentAt(q, r);
    }

    public updateAgentPosition(agent: Agent, newQ: number, newR: number) {
        this.map.updateAgentPosition(agent, newQ, newR);
    }

    public pushEvent(type: GameEventType, pos: {x: number, y: number}, opts: any = {}) {
        const evt = EventPool.get(type, pos, opts);
        if (type === 'KILL' && opts.sourceId) {
            this.director.forceFocus(this, opts.sourceId, 2.5);
        } else if (type === 'CAST_START' && opts.skill?.tag === 'ULT' && opts.sourceId) {
            this.director.forceFocus(this, opts.sourceId, 3.5); // Extend Ult focus time
        }
        this.events.push(evt);
    }

    public play() {
        if (!this.isRunning) {
            this.agents.forEach(a => a.saveState());
            this.state.time.battleTime = 0;
            this.logger.clear();
            this.victorySystem.reset(this);
            this.sessionState.killStreaks.clear();
            this.sessionState.firstBloodTriggered = false;
            this.log(null, 'SYSTEM', '開始', null, '戰鬥分析開始');
            this.bus.emit('GAME_START', {});
        }
        this.map.clearAgents();
        this.agents.forEach(a => {
            a.skills = a.skillIds.map(id => this.skillDB.find(s => s.id === id) || null);
            a.bt = this.ai.buildAI(a, this); 
            a.animState = AnimState.IDLE;
            if (a.hp > 0) this.map.registerAgent(a);
        });
        this.isRunning = true;
    }

    public stop() { this.isRunning = false; }

    public restart() {
        this.stop();
        this.victorySystem.reset(this);
        this.state.time.battleTime = 0;
        this.map.clearAgents();
        this.state.hazards.clear(); 
        this.director.reset(this);
        this.sessionState.killStreaks.clear();
        this.sessionState.firstBloodTriggered = false;
        this.agents.forEach(a => {
            a.reset(this.mapConfig);
            a.skills = a.skillIds.map(id => this.skillDB.find(s => s.id === id) || null);
            this.map.registerAgent(a);
        });
        this.projectiles = [];
        if (this.renderer) {
            this.renderer.reset();
            this.renderer.grid.reset(); 
            this.renderer.vfx.reset(); 
        }
        this.log(null, 'SYSTEM', '重置', null, '戰場狀態已重置');
        this.bus.emit('GAME_RESET', {});
    }

    public clear(keepScene: boolean = false) {
        this.stop();
        this.agents = [];
        this.projectiles = [];
        this.map.clearAgents();
        this.state.hazards.clear(); 
        this.map.obstacles.clear();
        this.map.obstaclesHash.clear();
        this.director.reset(this);
        this.logger.clear();
        if (this.renderer) {
            this.renderer.reset();
            this.renderer.grid.reset();
            this.renderer.vfx.reset();
        }
        if (!keepScene) this.map.randomizeEnvironment(this); 
        else this.map.rebuildMap(this); 
        this.bus.emit('GAME_CLEAR', {});
    }

    public tick(dt: number) {
        if (!this.isRunning) return;
        this.timeSystem.update(dt, this);
        this.events.length = 0; 

        // Director runs BEFORE entities to set up the camera target for this frame
        this.director.update(this, dt);

        this.zones.update(this); 
        if (this.victorySystem.check(this)) {
            this.victorySystem.updateFinishing(dt, this);
            this.updateEntities(dt);
            return;
        }
        this.updateEntities(dt);
    }

    private updateEntities(dt: number) {
        this.physics.update(dt, this);
        for (const a of this.agents) {
            if (a.hitFlashTimer > 0) a.hitFlashTimer -= dt;
            if (a.hp <= 0) {
                this.agentManager.handleDeadState(a, this);
                continue;
            }
            this.cooldowns.update(a, dt);
            this.effects.update(a, dt, this);
            this.controls.update(a, dt, this);
            if (a.isMoving && a.path.length > 0 && a.stunTimer <= 0) {
                this.movement.updateMovement(a, dt, this);
            }
            if (a.bt) {
                const resetTree = (node: BTNode) => { 
                    node.status = null; 
                    if (node.c) node.c.forEach(resetTree); 
                };
                resetTree(a.bt);
                a.bt.tick(a);
            }
        }
        this.combat.update(dt, this);
        this.hazardSystem.update(dt, this); 
        this.movement.resolveStacking(this);
        this.announcer.update(dt, this);
    }

    public log(agent: Agent | null, type: LogActionType, actionName: string, targetInfo: string | null, detail: string = '') {
        this.logger.log(this.battleTime, this.battleTime * 10, agent, type, actionName, targetInfo, detail);
    }

    public getEffectiveRange(a: Hex, targetQ: number, targetR: number, baseRange: number): number {
        return this.movement.getEffectiveRange(a, targetQ, targetR, baseRange, this);
    }

    public calculateOptimalTarget(source: Agent, skill: Skill) {
        return this.movement.calculateOptimalTarget(source, skill, this);
    }

    public moveAgentToHex(a: Agent, targetHex: Hex, r: number, speedMult: number = 1.0): NodeState {
        return this.movement.moveAgentToHex(a, targetHex, r, this, speedMult);
    }

    public initiateCast(a: Agent, skillIdx: number): NodeState {
        return this.combat.initiateCast(a, skillIdx, this);
    }

    public updateTarget(a: Agent) {
        this.movement.updateTarget(a, this);
    }
}

import { useRef, useEffect, MutableRefObject, useState } from 'react';
import { GameEngine, Agent } from '../engine/game';
import { ToolType, Hex, Team, Role } from '../types';
import { HexUtils, Vector } from '../engine/utils';
import { GameRenderer } from '../engine/renderer';
interface GameInputProps {
    canvasRef: MutableRefObject<HTMLCanvasElement | null>;
    engine: GameEngine;
    rendererRef: MutableRefObject<GameRenderer>;
    cameraRef: MutableRefObject<{ x: number; y: number; zoom: number }>;
    tool: ToolType;
    selectedObstacle: string;
    hpInput: number;
    spawnMode: 'RANDOM' | 'DRAFT';
    draftRole: Role;
    winner: Team | null;
    onSelect: (a: Agent | null) => void;
}
type InteractionMode = 'IDLE' | 'DOWN' | 'DRAG_UNIT' | 'DRAG_OBS' | 'PAINT' | 'PAN';
export const useGameInput = (props: GameInputProps) => {
    const { canvasRef, engine, rendererRef, cameraRef, tool, selectedObstacle, hpInput, spawnMode, draftRole, winner, onSelect } = props;
    const [pressedAgent, setPressedAgent] = useState<Agent | null>(null);
    const [draggedObstacle, setDraggedObstacle] = useState<any>(null);
    const interactionMode = useRef<InteractionMode>('IDLE');
    const lastPointerPos = useRef<{x: number, y: number} | null>(null);
    const pressStartPos = useRef<{x: number, y: number} | null>(null);
    const lastPaintHex = useRef<string>("");
    const pressedAgentRef = useRef<Agent | null>(null);
    const draggedObstacleRef = useRef<any>(null);
    const hoveredHexRef = useRef<Hex | null>(null);
    const activePointers = useRef<Set<number>>(new Set());
    const configRef = useRef({ tool, selectedObstacle, hpInput, spawnMode, draftRole, winner });
    useEffect(() => { configRef.current = { tool, selectedObstacle, hpInput, spawnMode, draftRole, winner }; }, [tool, selectedObstacle, hpInput, spawnMode, draftRole, winner]);
    const getHexFromCoords = (sx: number, sy: number) => {
        if (!canvasRef.current || !rendererRef.current) return null;
        const rect = canvasRef.current.getBoundingClientRect();
        return rendererRef.current.getHexAtScreenPoint(sx, sy, rect.width, rect.height, cameraRef.current, engine);
    };
    const handlePointerDown = (e: PointerEvent) => {
        activePointers.current.add(e.pointerId);
        if (activePointers.current.size > 1) { interactionMode.current = 'IDLE'; return; }
        if (e.pointerType === 'mouse' && e.button !== 0) return;
        const cvs = canvasRef.current;
        if (!cvs) return;
        const rect = cvs.getBoundingClientRect();
        const sx = e.clientX - rect.left, sy = e.clientY - rect.top;
        pressStartPos.current = { x: sx, y: sy };
        lastPointerPos.current = { x: sx, y: sy };
        lastPaintHex.current = "";
        const h = getHexFromCoords(sx, sy);
        const agent = h ? engine.getAgentAt(h.q, h.r) : undefined;

        if (agent) { 
            pressedAgentRef.current = agent; 
            setPressedAgent(agent); 
        }
        else if (h && !engine.isRunning && configRef.current.tool === ToolType.SELECT && engine.hasObstacle(h.q, h.r)) {
            const obsType = engine.map.obstacles.get(HexUtils.key(h));
            const obj = { type: obsType, originQ: h.q, originR: h.r, px: 0, py: 0 };
            draggedObstacleRef.current = obj;
            setDraggedObstacle(obj);
        }
        interactionMode.current = 'DOWN';
        cvs.setPointerCapture(e.pointerId);
    };
    const handlePointerMove = (e: PointerEvent) => {
        if (!lastPointerPos.current || activePointers.current.size > 1) return;
        const cvs = canvasRef.current;
        if (!cvs) return;
        const rect = cvs.getBoundingClientRect();
        const sx = e.clientX - rect.left, sy = e.clientY - rect.top;
        const dx = sx - lastPointerPos.current.x, dy = sy - lastPointerPos.current.y;
        const h = getHexFromCoords(sx, sy);
        hoveredHexRef.current = (h && engine.isValid(h.q, h.r)) ? h : null;
        if (interactionMode.current === 'DOWN' && pressStartPos.current) {
            const dist = Vector.dist(pressStartPos.current, {x: sx, y: sy});
            if (dist > 8) {
                if (!engine.isRunning && configRef.current.tool === ToolType.SELECT) {
                    if (pressedAgentRef.current) interactionMode.current = 'DRAG_UNIT';
                    else if (draggedObstacleRef.current) { 
                        interactionMode.current = 'DRAG_OBS'; 
                        engine.map.removeObstacle(draggedObstacleRef.current.originQ, draggedObstacleRef.current.originR); 
                    }
                    else interactionMode.current = 'PAN';
                } else if (!engine.isRunning && configRef.current.tool !== ToolType.SELECT) interactionMode.current = 'PAINT';
                else interactionMode.current = 'PAN';
            }
        }
        if (interactionMode.current === 'PAN') { 
            // 如果玩家手動拖曳，通知 CameraSystem 暫停自動導播
            if (rendererRef.current?.camera) {
                rendererRef.current.camera.applyPanOffset(dx, dy);
            }
            // 同時更新 React 的 ref 狀態供其他組件讀取 (HUD等)
            if (cameraRef.current) {
                // 注意：這裡其實是把「期望位置」反饋給 React 狀態
                // 但真正的渲染位置由 CameraSystem 物理計算決定
            }
            cvs.style.cursor = 'move'; 
        }
        else if (interactionMode.current === 'DRAG_UNIT' && pressedAgentRef.current) {
            const { x: camX, y: camY, zoom } = cameraRef.current;
            const cx = rect.width / 2, cy = rect.height / 2;
            const terrainH = h ? rendererRef.current.getTerrainHeight(h.q, h.r, engine) : 0;
            pressedAgentRef.current.px = (sx - cx) / zoom + camX;
            pressedAgentRef.current.py = (sy - cy) / zoom + camY + terrainH;
            cvs.style.cursor = 'grabbing';
        }
        else if (interactionMode.current === 'PAINT' && h) executePaintAction(h);
        lastPointerPos.current = { x: sx, y: sy };
    };
    const handlePointerUp = (e: PointerEvent) => {
        activePointers.current.delete(e.pointerId);
        const cvs = canvasRef.current;
        if (!cvs) return;
        if (interactionMode.current === 'DOWN') onSelect(pressedAgentRef.current);
        else if (interactionMode.current === 'DRAG_UNIT' && pressedAgentRef.current) {
            const a = pressedAgentRef.current;
            const h = getHexFromCoords(e.clientX - cvs.getBoundingClientRect().left, e.clientY - cvs.getBoundingClientRect().top);
            if (h && engine.isValid(h.q, h.r) && !engine.isBlocked(h.q, h.r, a.id)) { engine.updateAgentPosition(a, h.q, h.r); const p = HexUtils.toPx(h.q, h.r, engine.mapConfig); a.px = p.x; a.py = p.y; }
            else { const p = HexUtils.toPx(a.q, a.r, engine.mapConfig); a.px = p.x; a.py = p.y; }
        } else if (interactionMode.current === 'DRAG_OBS' && draggedObstacleRef.current) {
            const h = getHexFromCoords(e.clientX - cvs.getBoundingClientRect().left, e.clientY - cvs.getBoundingClientRect().top);
            if (h && engine.isValid(h.q, h.r) && !engine.getAgentAt(h.q, h.r) && !engine.hasObstacle(h.q, h.r)) engine.map.setObstacle(h.q, h.r, draggedObstacleRef.current.type);
            else engine.map.setObstacle(draggedObstacleRef.current.originQ, draggedObstacleRef.current.originR, draggedObstacleRef.current.type);
        }
        interactionMode.current = 'IDLE';
        pressedAgentRef.current = null; setPressedAgent(null);
        draggedObstacleRef.current = null; setDraggedObstacle(null);
        cvs.style.cursor = 'default';
        cvs.releasePointerCapture(e.pointerId);
    };
    const executePaintAction = (h: Hex) => {
        const { tool, winner, selectedObstacle, spawnMode, draftRole, hpInput } = configRef.current;
        if (engine.isRunning || winner !== null) return;
        const k = HexUtils.key(h);
        if (lastPaintHex.current === k) return; 
        lastPaintHex.current = k;
        if (tool === ToolType.DELETE) { engine.map.removeObstacle(h.q, h.r); engine.removeAgent(h.q, h.r); }
        else if (tool === ToolType.OBSTACLE) { engine.removeAgent(h.q, h.r); engine.map.setObstacle(h.q, h.r, selectedObstacle); }
        else if (tool === ToolType.ADD_BLUE || tool === ToolType.ADD_RED) {
            const existing = engine.getAgentAt(h.q, h.r);
            if (!existing && !engine.hasObstacle(h.q, h.r)) {
                let agent = engine.addAgent(tool === ToolType.ADD_BLUE ? Team.BLUE : Team.RED, h.q, h.r, hpInput);
                if (agent && spawnMode === 'DRAFT') { agent.role = draftRole; agent.saveState(); agent.reset(engine.mapConfig); }
            }
        }
    };
    useEffect(() => {
        const cvs = canvasRef.current;
        if (!cvs) return;
        cvs.addEventListener('pointerdown', handlePointerDown);
        cvs.addEventListener('pointermove', handlePointerMove);
        cvs.addEventListener('pointerup', handlePointerUp);
        cvs.addEventListener('pointercancel', handlePointerUp);
        return () => {
            cvs.removeEventListener('pointerdown', handlePointerDown);
            cvs.removeEventListener('pointermove', handlePointerMove);
            cvs.removeEventListener('pointerup', handlePointerUp);
            cvs.removeEventListener('pointercancel', handlePointerUp);
        };
    }, []);
    return { hoveredHexRef, pressedAgent, draggedObstacle };
};

import { useEffect, useRef, MutableRefObject } from 'react';

interface CameraControlProps {
    canvasRef: MutableRefObject<HTMLCanvasElement | null>;
    cameraRef: MutableRefObject<{ x: number; y: number; zoom: number }>;
    onZoom: (delta: number) => void;
    engine: any;
}

/**
 * 攝像機交互控制器 v26.0
 * 縮放操作也會暫時覆蓋自動運鏡
 */
export const useCameraControl = ({ canvasRef, cameraRef, onZoom, engine }: CameraControlProps) => {
    const lastPinchDist = useRef<number>(0);

    useEffect(() => {
        const cvs = canvasRef.current;
        if (!cvs) return;

        const notifyEngine = (newZoom: number) => {
            if (engine.renderer && engine.renderer.camera) {
                engine.renderer.camera.applyZoom(newZoom);
            }
        };

        const onWheel = (e: WheelEvent) => {
            e.preventDefault();
            const delta = e.deltaY > 0 ? -0.15 : 0.15;
            onZoom(delta);
            // Notify physics system
            notifyEngine(cameraRef.current.zoom);
        };

        const onTouchStart = (e: TouchEvent) => {
            if (e.touches.length === 2) {
                e.preventDefault();
                const t1 = e.touches[0];
                const t2 = e.touches[1];
                lastPinchDist.current = Math.hypot(t1.clientX - t2.clientX, t1.clientY - t2.clientY);
            }
        };

        const onTouchMove = (e: TouchEvent) => {
            if (e.touches.length === 2) {
                e.preventDefault();
                const t1 = e.touches[0];
                const t2 = e.touches[1];
                const dist = Math.hypot(t1.clientX - t2.clientX, t1.clientY - t2.clientY);
                if (lastPinchDist.current > 0) {
                    const delta = (dist - lastPinchDist.current) * 0.008;
                    onZoom(delta);
                    // Notify physics system
                    notifyEngine(cameraRef.current.zoom);
                }
                lastPinchDist.current = dist;
            }
        };

        cvs.addEventListener('wheel', onWheel, { passive: false });
        cvs.addEventListener('touchstart', onTouchStart, { passive: false });
        cvs.addEventListener('touchmove', onTouchMove, { passive: false });

        return () => {
            cvs.removeEventListener('wheel', onWheel);
            cvs.removeEventListener('touchstart', onTouchStart);
            cvs.removeEventListener('touchmove', onTouchMove);
        };
    }, [canvasRef, onZoom, engine]);
};

export interface Camera {
    x: number;
    y: number;
    zoom: number;
}

export class CameraSystem {
    // Current State
    public x: number = 0;
    public y: number = 0;
    public zoom: number = 1.0;

    // Target State (Where the director or physics wants to go)
    private targetX: number = 0;
    private targetY: number = 0;
    private targetZoom: number = 1.0;

    // Physics Parameters (Exposed for UI)
    // Lower stiffness = Heavier, slower camera (Cinematic)
    // Higher stiffness = Snappy, responsive camera (Arcade)
    public followStiffness: number = 0.8; // Default lowered from 3.0 for cinematic feel
    public zoomStiffness: number = 1.5;   // Default lowered from 2.0

    // Mode Control
    private manualOverrideTimer: number = 0; // 手動操作後的冷卻時間
    private isManualControlling: boolean = false;

    private trauma: number = 0;
    private readonly DECAY_RATE = 8.0;

    constructor() {}

    // 初始化或瞬間跳轉
    public snapTo(x: number, y: number, zoom: number) {
        this.x = this.targetX = x;
        this.y = this.targetY = y;
        this.zoom = this.targetZoom = zoom;
    }

    public reset() { 
        this.trauma = 0; 
        this.manualOverrideTimer = 0;
    }

    // 外部同步 (React State -> Engine)
    public sync(camera: Camera) {
        if (this.isManualControlling) {
            this.targetX = camera.x;
            this.targetY = camera.y;
            this.targetZoom = camera.zoom;
        }
    }

    // 當玩家拖曳畫面時呼叫
    public applyPanOffset(dx: number, dy: number) {
        this.isManualControlling = true;
        this.manualOverrideTimer = 2.0; // 手動操作後，暫停導播 2 秒

        const factor = 1.0 / this.zoom;
        const worldDx = dx * factor;
        const worldDy = dy * factor;

        // 直接操縱：立即更新位置以達到跟手感
        this.x -= worldDx;
        this.y -= worldDy;
        this.targetX = this.x;
        this.targetY = this.y;
    }

    public applyZoom(targetZoom: number) {
        this.targetZoom = targetZoom;
        this.manualOverrideTimer = 1.0; 
    }

    // 導播系統的輸入接口
    public setDirectorTarget(x: number, y: number, zoom: number) {
        // 只有在非手動模式下，導播系統才能控制目標點
        if (this.manualOverrideTimer <= 0) {
            this.isManualControlling = false;
            this.targetX = x;
            this.targetY = y;
            this.targetZoom = zoom;
        }
    }

    public addTrauma(amount: number) {
        this.trauma = Math.min(1.0, this.trauma + amount);
    }

    public getTrauma(): number {
        return this.trauma;
    }

    public update(dt: number) {
        // 1. Trauma Decay
        if (this.trauma > 0) {
            this.trauma = Math.max(0, this.trauma - dt * this.DECAY_RATE);
        }

        // 2. Manual Timer Decay
        if (this.manualOverrideTimer > 0) {
            this.manualOverrideTimer -= dt;
            if (this.manualOverrideTimer <= 0) {
                this.isManualControlling = false;
            }
        }

        // 3. Cinematic Smoothing (Exponential Interpolation)
        // 使用 dt 相關的 Lerp 公式: Current += (Target - Current) * (1 - exp(-speed * dt))
        // 這保證了 Frame Rate 獨立性且極度平滑

        // Position Smoothing
        // 使用 this.followStiffness 參數控制速度
        const panFactor = 1.0 - Math.exp(-this.followStiffness * dt);
        this.x += (this.targetX - this.x) * panFactor;
        this.y += (this.targetY - this.y) * panFactor;

        // Zoom Smoothing (Slower)
        const zoomFactor = 1.0 - Math.exp(-this.zoomStiffness * dt);
        this.zoom += (this.targetZoom - this.zoom) * zoomFactor;
    }

    public applyTransform(ctx: CanvasRenderingContext2D, width: number, height: number) {
        const cx = width / 2;
        const cy = height / 2;

        let shakeX = 0, shakeY = 0;
        if (this.trauma > 0) {
            const p = this.trauma * this.trauma;
            const maxShake = 30 * this.zoom; 
            const angle = Math.random() * Math.PI * 2;
            shakeX = Math.cos(angle) * maxShake * p;
            shakeY = Math.sin(angle) * maxShake * p;
        }

        const targetTx = cx - (this.x + shakeX) * this.zoom;
        const targetTy = cy - (this.y + shakeY) * this.zoom;

        ctx.translate(targetTx, targetTy); 
        ctx.scale(this.zoom, this.zoom);
    }
}

import { GameEngine, Agent } from "../game";
import { HexUtils } from "../utils";
import { Point } from "../../types";

export class DirectorSystem {
    // Configuration
    private readonly IDLE_ZOOM = 0.9;
    private readonly COMBAT_ZOOM = 1.15;
    private readonly ULT_ZOOM = 1.45;

    // Controls
    public enabled: boolean = true;

    // State
    private currentFocusPoint: Point = { x: 0, y: 0 };
    private currentZoomLevel: number = 1.0;

    // 興趣點平滑過渡用
    private lastCentroidX: number = 0;
    private lastCentroidY: number = 0;
    private hasInitialized: boolean = false;

    public reset(engine: GameEngine) {
        const ds = engine.state.director;
        ds.targetId = null;
        ds.focusTimer = 0;
        ds.priorityTimer = 0;
        this.hasInitialized = false;
        // Default to enabled on reset
        this.enabled = true;
    }

    public forceFocus(engine: GameEngine, id: string, duration: number = 2.0) {
        const ds = engine.state.director;
        ds.targetId = id;
        ds.priorityTimer = duration; // 優先權計時器，防止被普通邏輯覆蓋
        ds.focusTimer = duration;
    }

    public update(engine: GameEngine, dt: number) {
        if (!this.enabled) return;

        const ds = engine.state.director;

        // 1. Timer Logic
        if (ds.priorityTimer > 0) ds.priorityTimer -= dt;
        if (ds.focusTimer > 0) ds.focusTimer -= dt;

        // 2. Select Target (Decision Making)
        this.decideTarget(engine, ds);

        // 3. Calculate Cinematic Frame (Computation)
        const frame = this.calculateFrame(engine, ds.targetId);

        // 4. Push to Camera System (Action)
        if (engine.renderer && frame) {
            engine.renderer.camera.setDirectorTarget(frame.x, frame.y, frame.zoom);
        }
    }

    private decideTarget(engine: GameEngine, ds: any) {
        // 如果有強制優先權 (如奧義剛放)，不切換目標
        if (ds.priorityTimer > 0) return;

        // 如果當前目標無效或計時結束，尋找新目標
        let needNewTarget = false;

        if (ds.targetId) {
            const current = engine.agents.find(a => a.id === ds.targetId);
            if (!current || current.hp <= 0 || current.banished) {
                needNewTarget = true;
            } else if (ds.focusTimer <= 0) {
                // 時間到，嘗試切換更有趣的目標
                needNewTarget = true; 
            }
        } else {
            needNewTarget = true;
        }

        if (needNewTarget) {
            const bestCandidate = this.findBestCandidate(engine);
            if (bestCandidate) {
                // 如果目標改變了，設定新的關注時間
                if (ds.targetId !== bestCandidate.id) {
                    ds.targetId = bestCandidate.id;
                    // 根據動作給予不同的鏡頭時間
                    // 奧義/施法：給多一點時間 (3-4s)
                    // 移動/被打：給少一點時間 (2-3s)
                    const isAction = bestCandidate.castingSkillIdx !== -1;
                    ds.focusTimer = isAction ? 4.0 : 2.5;
                }
            } else {
                // 沒人活著，清空目標 (鏡頭將飄向戰場中心)
                ds.targetId = null;
            }
        }
    }

    private findBestCandidate(engine: GameEngine): Agent | null {
        let candidates: Agent[] = [];
        let maxScore = -1;
        let best: Agent | null = null;

        for (const a of engine.agents) {
            if (a.hp <= 0 || a.banished) continue;

            // 評分系統 (Director Scoring)
            let score = Math.random() * 10; // 基礎隨機性，避免死板

            // A. 狀態加權
            if (a.castingSkillIdx !== -1) {
                const skill = a.skills[a.castingSkillIdx];
                if (skill?.tag === 'ULT') score += 50; // 奧義極高權重
                else if (skill?.tag === 'ACTIVE') score += 20;
                else score += 5; // 普攻
            }
            if (a.hitFlashTimer > 0) score += 15; // 正在被打
            if (a.isMoving) score += 5;

            // B. 職業加權 (DPS 和 Tank 打架比較好看)
            if (a.role === 'WARRIOR' || a.role === 'TANK') score += 2;

            if (score > maxScore) {
                maxScore = score;
                best = a;
            }
        }
        return best;
    }

    private calculateFrame(engine: GameEngine, targetId: string | null): { x: number, y: number, zoom: number } | null {
        let targetX = 0;
        let targetY = 0;
        let targetZoom = this.IDLE_ZOOM;

        const mainActor = targetId ? engine.agents.find(a => a.id === targetId) : null;

        if (mainActor && mainActor.hp > 0) {
            // --- 戰鬥構圖邏輯 ---

            // 1. 基礎位置：主角
            targetX = mainActor.px;
            targetY = mainActor.py;

            // 2. 關係修正：如果有攻擊目標，鏡頭移向兩者中間
            if (mainActor.target && mainActor.target.hp > 0) {
                const t = mainActor.target;

                // 權重平均：主角 60%，目標 40% (讓鏡頭稍微偏向主角)
                targetX = mainActor.px * 0.6 + t.px * 0.4;
                targetY = mainActor.py * 0.6 + t.py * 0.4;

                // 3. 動態縮放：根據距離調整
                // 距離越近，Zoom 越大 (Close up fight)
                const dist = HexUtils.dist(mainActor, t); // Hex distance
                if (dist < 2) targetZoom = this.COMBAT_ZOOM; // Close combat
                else if (dist < 6) targetZoom = 1.05;        // Mid range
                else targetZoom = 0.95;                      // Long range sniping

            } else if (mainActor.isMoving && mainActor.path.length > 0) {
                // 如果在移動，鏡頭稍微看向前方 (Look Ahead)
                // 預判 100px
                targetX += mainActor.physics.vx * 0.5; 
                targetY += mainActor.physics.vy * 0.5;
                targetZoom = 1.0;
            } else {
                // 待機特寫
                targetZoom = 1.1; 
            }

            // 4. 奧義特寫 override
            if (mainActor.castingSkillIdx !== -1) {
                const skill = mainActor.skills[mainActor.castingSkillIdx];
                if (skill?.tag === 'ULT') {
                    // 奧義時，鏡頭聚焦於施法者，並拉近
                    targetX = mainActor.px;
                    targetY = mainActor.py - 20; // 稍微抬高一點構圖
                    targetZoom = this.ULT_ZOOM;
                }
            }

        } else {
            // --- 廣角模式 ---
            // 沒有特定目標，計算所有存活單位的重心
            let sumX = 0, sumY = 0, count = 0;
            for (const a of engine.agents) {
                if (a.hp > 0) {
                    sumX += a.px;
                    sumY += a.py;
                    count++;
                }
            }

            if (count > 0) {
                targetX = sumX / count;
                targetY = sumY / count;
                // 根據單位分佈廣度調整 Zoom? 暫時固定廣角
                targetZoom = this.IDLE_ZOOM;
            } else {
                // 完全沒人，看地圖中心
                const centerHex = { q: Math.floor(engine.mapConfig.w/2), r: Math.floor(engine.mapConfig.h/2) };
                const centerPx = HexUtils.toPx(centerHex.q, centerHex.r, engine.mapConfig);
                targetX = centerPx.x;
                targetY = centerPx.y;
                targetZoom = 0.8;
            }
        }

        // --- 平滑重心 (Stabilizer) ---
        // 避免因為目標切換導致瞬間座標跳變
        if (!this.hasInitialized) {
            this.lastCentroidX = targetX;
            this.lastCentroidY = targetY;
            this.hasInitialized = true;
        }

        // 這裡做一層極輕微的緩衝，防止計算出的 frame 跳動
        // 真正的物理慣性由 CameraSystem 處理
        this.lastCentroidX += (targetX - this.lastCentroidX) * 0.1;
        this.lastCentroidY += (targetY - this.lastCentroidY) * 0.1;

        return { x: targetX, y: targetY, zoom: targetZoom };
    }
}

import React, { useRef, useState, useEffect } from 'react';
import { MatrixConfig, LayoutPreset } from './types';
import { DEFAULT_MATRIX_CONFIG } from './defaults';
import { useMatrixRain } from './useMatrixRain';
import { ShowcaseSettings } from './ShowcaseSettings';
import { Icons } from '../icons';
import { GameEngine } from '../../../engine/game';

interface ShowcaseOverlayProps {
    onEnter: () => void;
    timeScale: number;
    setTimeScale: (v: number) => void;
    engine?: GameEngine; // Add engine prop
}

export const ShowcaseOverlay: React.FC<ShowcaseOverlayProps> = ({ onEnter, timeScale, setTimeScale, engine }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const [config, setConfig] = useState<MatrixConfig>(DEFAULT_MATRIX_CONFIG);
    const [layout, setLayout] = useState<LayoutPreset>('BOTTOM_CENTER');
    const [showSettings, setShowSettings] = useState(false);

    // Track window size for canvas init
    const [viewport, setViewport] = useState({ w: window.innerWidth, h: window.innerHeight });

    useEffect(() => {
        const handleResize = () => setViewport({ w: window.innerWidth, h: window.innerHeight });
        window.addEventListener('resize', handleResize);
        return () => window.removeEventListener('resize', handleResize);
    }, []);

    // Hook: Handles the Matrix Rain rendering on the transparent canvas
    useMatrixRain(canvasRef, config, viewport.w, viewport.h);

    // Helper: Determine UI Layout classes
    const getLayoutClasses = () => {
        switch (layout) {
            case 'CENTER': 
                return 'inset-0 flex-col justify-center items-center text-center p-4 md:p-8';
            case 'BOTTOM_CENTER': 
                return 'bottom-12 left-0 right-0 mx-auto w-full max-w-[calc(100vw-4rem)] md:max-w-5xl flex-col md:flex-row justify-between items-center';
            case 'BOTTOM_LEFT': 
                return 'bottom-10 left-6 w-[min(320px,90vw)] md:w-[400px] flex-col justify-end items-start';
            case 'BOTTOM_RIGHT': 
                return 'bottom-10 right-6 w-[min(320px,90vw)] md:w-[400px] flex-col justify-end items-end text-right';
            default: 
                return 'inset-0 justify-center items-center';
        }
    };

    const isCompact = layout !== 'CENTER';
    const isWideBar = layout === 'BOTTOM_CENTER';

    const getRgbaBg = (hex: string, alpha: number) => {
        const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
        if (!result) return `rgba(0,0,0,${alpha})`;
        const r = parseInt(result[1], 16);
        const g = parseInt(result[2], 16);
        const b = parseInt(result[3], 16);
        return `rgba(${r}, ${g}, ${b}, ${alpha})`;
    };

    return (
        <div className="absolute inset-0 z-50 overflow-hidden pointer-events-none">

            {/* LAYER 1: Background Color Overlay */}
            <div 
                className="absolute inset-0 transition-colors duration-300"
                style={{ backgroundColor: getRgbaBg(config.bgColor, config.enabled ? config.bgOpacity : 0) }}
            ></div>

            {/* LAYER 2: Matrix Rain Canvas */}
            <canvas 
                ref={canvasRef} 
                className="absolute inset-0 block w-full h-full pointer-events-none mix-blend-screen"
            />

            {/* LAYER 3: CRT Scanline / Vignette Effects */}
            {config.enabled && config.bgOpacity > 0.1 && (
                <>
                    <div className="absolute inset-0 bg-[url('data:image/svg+xml;base64,PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIHdpZHRoPSI0IiBoZWlnaHQ9IjQiPgo8cmVjdCB3aWR0aD0iNCIgaGVpZ2h0PSI0IiBmaWxsPSIjMDAwIiAvPgo8cmVjdCB3aWR0aD0iNCIgaGVpZ2h0PSIxIiBmaWxsPSJyZ2JhKDI1NSwgMjU1LDI1NSwgMC4wNSkiIC8+Cjwvc3ZnPg==')] opacity-30 pointer-events-none"></div>
                    <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,transparent_0%,rgba(0,0,0,0.4)_90%)] pointer-events-none"></div>
                </>
            )}

            {/* LAYER 4: UI Content */}
            <div className={`absolute z-[55] flex animate-slide-up pointer-events-none transition-all duration-500 ${getLayoutClasses()}`}>

                {/* Main Liquid Card */}
                <div className={`liquid-card p-8 md:p-10 pointer-events-auto flex max-w-full ${isWideBar ? 'w-full flex-col md:flex-row items-center gap-8' : 'flex-col items-center gap-8 w-full'}`}>

                    {/* Content Text */}
                    <div className={`relative flex flex-col max-w-full ${isWideBar ? 'items-center md:items-start text-center md:text-left flex-1' : (layout.includes('RIGHT') ? 'items-end' : 'items-center')}`}>

                        {/* Header Badge */}
                        <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-cyan-950/30 border border-cyan-500/30 text-[10px] text-cyan-400 font-mono tracking-widest mb-4 shadow-[0_0_10px_rgba(6,182,212,0.2)]">
                            <span className="w-1.5 h-1.5 rounded-full bg-cyan-400 animate-pulse box-shadow-[0_0_5px_cyan]"></span>
                            <span>SYSTEM_READY</span>
                        </div>

                        <h1 className={`font-black text-transparent bg-clip-text bg-gradient-to-b from-white via-cyan-100 to-cyan-500 font-mono tracking-tighter drop-shadow-[0_0_30px_rgba(6,182,212,0.5)] ${isCompact ? 'text-5xl' : 'text-7xl md:text-8xl'}`}>
                            TACTICAL.OS
                        </h1>

                        <div className="text-slate-400 font-mono text-xs tracking-[0.4em] uppercase mt-3 opacity-80 mix-blend-plus-lighter">
                            v9.2 | SSOT Kernel Active
                        </div>
                    </div>

                    {/* Start Button */}
                    <div className={`relative shrink-0 ${isCompact && !isWideBar ? 'w-full' : ''}`}>
                        <button 
                            onClick={onEnter}
                            className={`group liquid-btn-primary rounded-2xl overflow-hidden transition-all duration-300 ${isWideBar ? 'px-16 py-6 w-full md:w-auto text-xl' : 'w-full px-12 py-5 text-lg'} shadow-[0_0_30px_rgba(6,182,212,0.2)]`}
                        >
                            <span className="relative flex items-center justify-center gap-4 z-10">
                                <span>INITIALIZE</span>
                                <Icons.Play className="w-5 h-5 fill-current group-hover:translate-x-1 transition-transform" />
                            </span>
                        </button>
                    </div>
                </div>
            </div>

            {/* LAYER 5: Controls */}
            <div className="absolute top-6 left-6 z-[60] pointer-events-auto">
                <button 
                    onClick={() => setShowSettings(!showSettings)}
                    className={`liquid-icon-btn hover:text-cyan-400 hover:border-cyan-500/50 hover:bg-white/10 ${showSettings ? 'text-cyan-400 border-cyan-500/50 bg-white/10' : 'text-slate-400'}`}
                    title="特效設定"
                >
                    <Icons.Settings className={`w-5 h-5 ${showSettings ? 'animate-spin-slow' : ''}`} />
                </button>
            </div>

            <ShowcaseSettings 
                show={showSettings} 
                onClose={() => setShowSettings(false)}
                config={config} 
                setConfig={setConfig} 
                timeScale={timeScale}
                setTimeScale={setTimeScale}
                layout={layout}
                setLayout={setLayout}
                engine={engine}
            />
        </div>
    );
};

import React, { useState, useEffect } from 'react';
