                                    onChange={(e) => toggleDirector(e.target.checked)}
                                />
                                <div className="w-7 h-4 bg-slate-700 rounded-full peer peer-checked:after:translate-x-full after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:rounded-full after:h-3 after:w-3 after:transition-all peer-checked:bg-cyan-500"></div>
                            </label>
                        </div>
                        <div className="space-y-2">
                            <div className="flex justify-between text-[10px] text-slate-500 font-bold uppercase tracking-wider">
                                <span>Follow Speed (Stiffness)</span>
                                <span className="font-mono text-cyan-300">{cameraStiffness.toFixed(1)}</span>
